function persist(){localStorage.setItem('docnova-cart',JSON.stringify(cart));localStorage.setItem('docnova-wishlist',JSON.stringify(wishlist));$('#count').textContent=cart.reduce((n,x)=>n+x.qty,0)}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3000)}
function modal(html,drawer=false){lastFocus=document.activeElement;const m=$('#modal');m.className=drawer?'drawer':'';m.innerHTML='<button class="close" aria-label="Close" onclick="closeModal()">×</button>'+html;if(!m.open)m.showModal();}
function closeModal(){$('#modal').close();lastFocus?.focus()}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
function save(id,el){wishlist=wishlist.includes(id)?wishlist.filter(x=>x!==id):[...wishlist,id];persist();if(el){el.textContent=wishlist.includes(id)?'♥':'♡';el.setAttribute('aria-pressed',wishlist.includes(id))}toast(wishlist.includes(id)?'Saved to your wishlist':'Removed from wishlist')}
function card(p){return `<article><div class="product-media ${p.device?'device-media':''}"><a href="#/product/${p.id}" aria-label="View ${p.name}"><img loading="lazy" src="${imageOf(p)}" alt="${p.name} in ${p.color}"><img class="alternate" loading="lazy" src="${imageOf(p,1)}" alt="Alternate view of ${p.name}"></a>${p.badge?`<span class="badge">${p.badge}</span>`:''}<button class="save" aria-label="Save ${p.name}" aria-pressed="${wishlist.includes(p.id)}" onclick="save('${p.id}',this)">${wishlist.includes(p.id)?'♥':'♡'}</button><button class="quick" onclick="quickView('${p.id}')">Quick view & add +</button></div><div class="product-info"><div class="row"><h3><a href="#/product/${p.id}">${p.name}</a></h3><span>${money(p.price)}</span></div><p>${p.device?'Medical device':p.fit+' · '+p.color}${p.old?' · Was '+money(p.old):''}</p><div class="swatches" ${p.device?'hidden':''}><span class="swatch" style="background:${colors[p.color]}" title="${p.color}"></span></div></div></article>`}
function reviews(){return `<section class="section g-reviews" aria-label="Google reviews"><div class="gr-wrap"><div class="gr-summary"><span class="eyebrow">GOOGLE REVIEWS</span><h2>Worn on shift.<br><em>Rated on Google.</em></h2><p class="gr-loading fine">Loading reviews from Google…</p></div><div class="gr-list" aria-live="polite"></div></div></section>`}
function home(){return homeHero+`<div class="trust home-trust"><span>UK-based · Cambridge</span><span>Men’s & women’s scrubs</span><span>Sizes S–XL</span><span>Medical essentials, thoughtfully selected</span></div><section class="section home-collections"><div class="section-heading"><div><span class="eyebrow">EXPLORE DOCNOVA</span><h2>Two collections.<br>One considered approach.</h2></div><p>What you wear. What you rely on.<br>Find your everyday essentials here.</p></div><div class="home-category-grid"><a class="home-category" href="#/shop?fit=Women"><img loading="lazy" src="assets/5-0.webp" alt="DocNova women’s Navy Blue scrubs"><div><span class="eyebrow">01 / MEDICAL APPAREL</span><h3>Women’s scrubs <span>↗</span></h3><p>Modern fits. Colours that feel like you.</p></div></a><a class="home-category" href="#/shop?fit=Men"><img loading="lazy" src="assets/9-0.webp" alt="DocNova men’s Green scrubs"><div><span class="eyebrow">02 / MEDICAL APPAREL</span><h3>Men’s scrubs <span>↗</span></h3><p>Considered comfort for your daily rotation.</p></div></a><a class="home-category device-category" href="#/shop?category=Medical%20Devices"><img loading="lazy" src="${photos.bp[0]}" alt="DocNova Upper Arm Blood Pressure Monitor"><div><span class="eyebrow">03 / MEDICAL DEVICES</span><h3>Essential Medical Devices <span>↗</span></h3><p>Blood pressure monitors & thermometers.</p></div></a></div></section><section class="section home-scrubs"><div class="section-heading"><div><span class="eyebrow">THE SCRUB COLLECTION</span><h2>Dress for your day.</h2></div><a class="text-link" href="#/shop?collection=Scrubs">Shop all scrubs ↗</a></div><div class="grid">${['nova-top','women-pink-top','men-royal-blue-top','nova-pant'].map(id=>products.find(p=>p.id===id)).filter(Boolean).map(card).join('')}</div><div class="home-fit-note"><span>Tops £44.99 · Trousers £49.99</span><a href="#/size-guide">Find your fit ↗</a></div></section><section class="section home-devices"><div class="device-story"><span class="eyebrow">THE MEDICAL DEVICE COLLECTION</span><h2>Small essentials.<br>A place in your<br><em>everyday routine.</em></h2><p>Explore the DocNova upper-arm blood pressure monitor and infrared thermometer. See product details and choose the right addition to your essentials.</p><a class="btn" href="#/shop?category=Medical%20Devices">Explore medical devices ↗</a></div><div class="grid">${products.filter(p=>p.device).map(card).join('')}</div></section><section class="home-brand"><span class="eyebrow">THE DOCNOVA APPROACH</span><h2>For the people who care.</h2><p>A professional wardrobe with a personal point of view. Practical essentials with a place in your day. Discover a more considered approach to medical apparel and everyday care.</p><a class="text-link" href="#/about">Get to know DocNova ↗</a></section>${reviews()}`}

$('#footer').innerHTML=`<div class="newsletter"><div><h2>A better everyday starts here.</h2><p>Subscribe for collection updates and 10% off with WELCOME10.</p></div><form onsubmit="newsletter(event)"><label class="sr" for="email"></label><input id="email" name="email" aria-label="Email address" type="email" required placeholder="Your email address"><button aria-label="Subscribe">Join us ↗</button></form></div><div class="columns"><div><a class="logo official-logo" href="#/" aria-label="DocNova home"><span class="logo-frame"><img src="assets/docnova-official-logo.png" alt="DocNova" width="1774" height="887"></span></a><p style="color:#c4c9d0;font-size:14px">For the people who care.<br>Designed for your every day.</p><button class="social" aria-label="Instagram" onclick="socialInfo()">◎</button><button class="social" aria-label="Pinterest" onclick="socialInfo()">Ⓟ</button></div><div><h3>Explore</h3><a href="#/shop">Shop all</a><a href="#/shop?fit=Women">Women</a><a href="#/shop?fit=Men">Men</a><a href="#/about">Our story</a></div><div><h3>Here to help</h3><a href="#/size-guide">Size & fit guide</a><a href="#/faq">FAQs</a><a href="#/track-order">Track your order</a><a href="#/shipping">Delivery & returns</a><a href="#/contact">Contact</a></div><div><h3>The details</h3><a href="#/reviews">Reviews</a><a href="#/privacy">Privacy policy</a><a href="#/terms">Terms of service</a><a href="#/wishlist">Your wishlist</a></div></div><div class="copyright"><span>© ${new Date().getFullYear()} DocNova. All rights reserved.</span><span>United Kingdom · GBP £ &nbsp; | &nbsp; Secure payments by Stripe <span id="footer-pay" class="footer-pay">${payMethodsMarkup()}</span></span></div>`;
