function shop(){const q=new URLSearchParams(location.hash.split('?')[1]||'');return `<div class="page-head"><span class="eyebrow">THE DOCNOVA COLLECTION</span><h1>Considered essentials.</h1><p>Modern scrubs. Effortless comfort. Find the pieces that work as hard as you do.</p></div><div class="shop-layout"><aside class="filters"><h3>Refine your edit</h3>${[['category','Category',['All','Tops','Pants','Sets','Medical Devices','Jackets','Underscrubs','Accessories']],['fit','Fit',['All','Women','Men']],['size','Size',['All',...sizes]],['color','Colour',['All',...Object.keys(colors)]],['price','Price',['All','Under £40','£40–£60','Over £60']],['fabric','Fabric',['All','Stretch blend']],['collection','Collection',['All','Scrubs','Core','Studio','Medical Essentials']]].map(([id,label,values])=>`<div><label for="filter-${id}">${label}</label><select id="filter-${id}" onchange="page=1;filterProducts()">${values.map(v=>`<option ${q.get(id)===v?'selected':''}>${v}</option>`).join('')}</select></div>`).join('')}<button class="text-link" style="margin-top:20px" onclick="document.querySelectorAll('.filters select').forEach(s=>s.selectedIndex=0);page=1;filterProducts()">Clear filters</button></aside><div><div class="shop-top"><span id="result-count"></span><select id="sort" aria-label="Sort products" onchange="page=1;filterProducts()"><option>Featured</option><option>Newest</option><option>Best-selling</option><option>Price: low to high</option><option>Price: high to low</option></select></div><div id="results" class="grid shop-grid"></div><div id="pagination" class="pagination"></div></div></div>`}
function filterProducts(){let result=products.filter(p=>['category','fit','color','fabric','collection'].every(k=>$('#filter-'+k).value==='All'||(k==='collection'&&$('#filter-'+k).value==='Scrubs'?!p.device:p[k]===$('#filter-'+k).value)));if($('#filter-size').value!=='All')result=result.filter(p=>!p.device);const price=$('#filter-price').value;if(price==='Under £40')result=result.filter(p=>p.price<40);if(price==='£40–£60')result=result.filter(p=>p.price>=40&&p.price<=60);if(price==='Over £60')result=result.filter(p=>p.price>60);const sort=$('#sort').value;if(sort.includes('low to high'))result.sort((a,b)=>a.price-b.price);if(sort.includes('high to low'))result.sort((a,b)=>b.price-a.price);if(sort==='Newest')result.reverse();if(sort==='Best-selling')result.sort((a,b)=>Number(b.badge==='BEST SELLER')-Number(a.badge==='BEST SELLER'));$('#result-count').textContent=result.length+' essentials';$('#results').innerHTML=result.length?result.slice((page-1)*9,page*9).map(card).join(''):`<div class="empty"><h2>Your next essential is on its way.</h2><p>There are no available pieces in this selection yet.</p><button class="btn" onclick="location.hash='/shop'">Explore current collection</button></div>`;$('#pagination').innerHTML=Array.from({length:Math.ceil(result.length/9)},(_,i)=>`<button aria-label="Page ${i+1}" aria-current="${page===i+1?'page':'false'}" onclick="page=${i+1};filterProducts();document.querySelector('.shop-top').scrollIntoView()">${i+1}</button>`).join('')}
function sizeControls(){return `<div class="choices">${sizes.map(s=>`<button data-size="${s}" onclick="selectSize('${s}',this)">${s}</button>`).join('')}</div><p id="size-error" class="fine" role="alert"></p>`}
function selectSize(s,el){selectedSize=s;el.parentElement.querySelectorAll('button').forEach(b=>{b.classList.toggle('selected',b===el);b.setAttribute('aria-pressed',b===el)});const err=$('#size-error');if(err)err.textContent=''}
function quickView(id){selectedProduct=products.find(p=>p.id===id);if(selectedProduct.device){deviceQuickView(selectedProduct);return}selectedSize='';const p=selectedProduct;modal(`<img src="${imageOf(p)}" style="width:150px;height:190px;float:left;margin:0 25px 20px 0" alt="${p.name}"><span class="eyebrow">${p.fit} · ${p.color}</span><h2>${p.name}</h2><p>${money(p.price)}</p><div style="clear:both">${colourOptions(p,true)}<label>Choose your size</label>${sizeControls()}<button class="btn full" onclick="addSelected()">Add to bag — ${money(p.price)}</button><p><a class="text-link" href="#/product/${id}" onclick="closeModal()">View full details ↗</a></p>${matchingPiece(p)}</div>`)}
function addSelected(buy=false){if(!$('#modal').open){const id=location.hash.split('/')[2];selectedProduct=products.find(p=>p.id===id)||selectedProduct;selectedSize=document.querySelector('#app [data-size].selected')?.dataset.size||'';}if(selectedProduct?.device)selectedSize='Standard';if(!selectedSize){const e=$('#size-error');if(e){e.textContent='Please choose a size to continue.';e.scrollIntoView({block:'center',behavior:'smooth'})}return}addToCart(selectedProduct.id,selectedSize);closeModal();if(buy)location.hash='/checkout';else openCart()}
function addToCart(id,size){if(!products.some(p=>p.id===id)||(!sizes.includes(size)&&!(size==='Standard'&&products.find(p=>p.id===id)?.device)))throw Error('Choose a valid product and size');const item=cart.find(x=>x.id===id&&x.size===size);if(item)item.qty++;else cart.push({id,size,qty:1});persist();return {id,size,quantity:cart.find(x=>x.id===id&&x.size===size).qty}}
function cartItems(edit=true){return cart.map((x,i)=>{const p=products.find(p=>p.id===x.id);return `<div class="cart-item"><img src="${imageOf(p)}" alt="${p.name}"><div><h3>${p.name}</h3><p>${p.device?'Medical device':p.color+' / '+x.size} · ${money(p.price)}</p>${edit?`<div class="quantity"><button aria-label="Decrease quantity" onclick="changeQty(${i},-1)">−</button><span>${x.qty}</span><button aria-label="Increase quantity" onclick="changeQty(${i},1)">+</button><button style="border:0;width:auto;font-size:12px" onclick="removeItem(${i})">Remove</button></div>`:`<span>Quantity: ${x.qty}</span>`}</div></div>`}).join('')}
let appliedCoupon=localStorage.getItem('docnova-coupon')==='WELCOME10'?'WELCOME10':'';
function subtotal(){return cart.reduce((n,x)=>n+Math.round(products.find(p=>p.id===x.id).price*100)*x.qty,0)/100}
function changeQty(i,n){cart[i].qty+=n;if(cart[i].qty<=0)cart.splice(i,1);persist();if(location.hash==='#/checkout')$('#app').innerHTML=checkout();openCart()}
function removeItem(i){cart.splice(i,1);persist();if(location.hash==='#/checkout')$('#app').innerHTML=checkout();openCart()}
function openCart(){modal(`<h2>Your bag <span style="font:16px Arial">(${cart.reduce((n,x)=>n+x.qty,0)})</span></h2>${cart.length?`<p class="fine">${subtotal()>=100?'Your order qualifies for complimentary delivery.':money(100-subtotal())+' away from complimentary delivery.'}</p>${cartItems()}<div class="cart-total"><span>Subtotal</span><span>${money(subtotal())}</span></div><p class="fine">UK delivery: £4.95, complimentary over £100.</p><button class="btn full" onclick="closeModal();location.hash='/checkout'">Continue to checkout ↗</button><p class="fine">Secure checkout by Stripe · Cards, Apple Pay, Google Pay &amp; more</p><button class="text-link" onclick="closeModal();location.hash='/shop'">Continue shopping</button>`:`<div class="empty"><p>Your everyday essentials are waiting.</p><button class="btn" onclick="closeModal();location.hash='/shop'">Explore scrubs</button></div>`}`,true)}
function productPage(id){const p=products.find(x=>x.id===id);if(!p)return '<div class="content"><h1>Product not found</h1><a href="#/shop">Return to collection</a></div>';selectedProduct=p;if(p.device){selectedSize='Standard';return devicePage(p)}selectedSize='';const gallery=photos[p.group].slice(0,6);return `<div class="pdp"><div><p class="fine"><a href="#/shop">Collection</a> / ${p.category} / ${p.name}</p><img id="main-photo" class="gallery-main" src="${imageOf(p)}" alt="${p.name} in ${p.color}. Click to enlarge." tabindex="0" role="button" onclick="zoomPhoto()" onkeydown="if(event.key==='Enter')zoomPhoto()"><div class="thumbs">${gallery.map((im,i)=>`<button aria-label="View photograph ${i+1}" onclick="document.querySelector('#main-photo').src='${im}'"><img src="${im}" alt="${p.name}, view ${i+1}"></button>`).join('')}</div><p class="fine">Styled as a complete look. ${p.category==='Sets'?'Includes one top (£44.99) and one trouser (£49.99). Combined price £94.98; no set discount.':'Includes '+p.category.toLowerCase()+' only; other items shown are styling.'}</p></div><div class="product-detail"><span class="eyebrow">THE ${p.collection.toUpperCase()} COLLECTION · ${p.fit.toUpperCase()}</span><h1>${p.name}</h1><p class="price">${money(p.price)} ${p.old?`<del>${money(p.old)}</del>`:''}</p><a class="fine text-link" href="#/reviews">★★★★★ Explore sample reviews</a><p style="margin-top:22px">A refined essential for your daily rotation. A clean silhouette, comfortable stretch and thoughtful details — so you can focus on what matters.</p>${colourOptions(p)}<div style="display:flex;justify-content:space-between"><label>Size</label><a class="text-link" href="#/size-guide">Size guide ↗</a></div>${sizeControls()}<p class="fine">A modern regular fit. Between sizes? Choose the larger size for a more relaxed feel.</p><div class="mobile-add"><button class="btn" onclick="addSelected()">Add to bag — ${money(p.price)}</button><button class="btn outline" onclick="addSelected(true)">Buy now</button></div><p class="fine">✓ Easy-care design &nbsp; ✓ Stretch comfort &nbsp; ✓ Professional fit</p>${matchingPiece(p)}${[['The details','A modern neckline, practical storage and an easy silhouette. Designed to feel comfortable through a busy day.'],['Fabric & care','Stretch-blend fabric concept. Exact composition and performance specifications require supplier confirmation. Proposed care: gentle cool wash with similar colours; follow the garment label before use.'],['Delivery & returns','Preview policy: UK delivery £4.95; complimentary over £100. Unworn items may be returned within 30 days in this demonstration. Live shipping and returns terms must be confirmed before launch.']].map(([h,t])=>`<details><summary>${h}</summary><p>${t}</p></details>`).join('')}</div></div><section class="section"><div class="section-heading"><h2>Complete your rotation.</h2><a class="text-link" href="#/shop">Shop all ↗</a></div><div class="grid">${products.filter(x=>x.id!==id&&x.fit===p.fit).slice(0,4).map(card).join('')}</div></section><section class="section" style="padding-top:0"><h2>You may also like.</h2><div class="grid">${products.filter(x=>x.id!==id&&x.fit!==p.fit).slice(0,4).map(card).join('')}</div></section>${reviews()}`}
